components.css:
.ds-run { font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; border: 1px solid var(--ink, #0e0d0c); border-radius: 3px; background: var(--ink, #0e0d0c); color: var(--tissue, #f3efe6); padding: 9px 18px; cursor: pointer; }
.ds-run:hover:not(:disabled) { background: color-mix(in srgb, var(--ink, #0e0d0c) 88%, var(--board, #c45a14)); }
.ds-run:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }
.ds-run:disabled { opacity: 0.38; cursor: not-allowed; }

.ds-board { font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; border: 1px solid var(--ink, #0e0d0c); border-radius: 3px; background: var(--board, #c45a14); color: var(--ink, #0e0d0c); padding: 9px 18px; cursor: pointer; }
.ds-board:hover:not(:disabled) { background: color-mix(in srgb, var(--tissue, #f3efe6) 35%, var(--board, #c45a14)); }
.ds-board:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }
.ds-board:disabled { opacity: 0.38; cursor: not-allowed; }

.ds-cancel { font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; border: 1px solid var(--brick, #b83a28); border-radius: 3px; background: var(--tissue, #f3efe6); color: var(--brick, #b83a28); padding: 9px 18px; cursor: pointer; }
.ds-cancel:hover:not(:disabled) { background: color-mix(in srgb, var(--tissue, #f3efe6) 35%, var(--board, #c45a14)); }
.ds-cancel:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }
.ds-cancel:disabled { opacity: 0.38; cursor: not-allowed; }

.ds-field { display: flex; flex-direction: column; gap: 6px; }
.ds-field > span { font-family: "Chivo Mono", ui-monospace, monospace; font-size: 11px; font-weight: 500; letter-spacing: 0.02em; color: color-mix(in srgb, var(--ink, #0e0d0c) 78%, var(--board, #c45a14)); }
.ds-textarea { width: 100%; min-height: 124px; font-family: "Chivo Mono", ui-monospace, monospace; font-size: 12px; font-weight: 400; line-height: 1.45; letter-spacing: 0; text-transform: none; color: var(--ink, #0e0d0c); background: var(--tissue, #f3efe6); border: 1px solid var(--ink, #0e0d0c); border-radius: 3px; padding: 8px 10px; caret-color: var(--ink, #0e0d0c); }
.ds-textarea:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }

.ds-chips { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 0; padding: 0; list-style: none; }
.ds-chip { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 6px 8px; border: 1px solid var(--ink, #0e0d0c); background: var(--tissue, #f3efe6); }
.ds-swatch { width: 22px; height: 22px; flex: none; border: 1px solid var(--ink, #0e0d0c); background: color-mix(in srgb, var(--ink, #0e0d0c) 10%, var(--tissue, #f3efe6)); }
.ds-chip-lit .ds-swatch { background: var(--forest, #4f6a38); }
.ds-chip-struck .ds-swatch { background: var(--brick, #b83a28); background-image: linear-gradient(135deg, transparent 44%, var(--ink, #0e0d0c) 44% 56%, transparent 56%); }
.ds-code { font-family: "Chivo Mono", ui-monospace, monospace; font-size: 12px; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; font-variant-numeric: tabular-nums; color: var(--ink, #0e0d0c); }

.ds-tag { display: inline-block; margin: 0 4px 4px 0; padding: 1px 6px 0; font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 13px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--tissue, #f3efe6); background: var(--ink, #0e0d0c); }
.ds-tag-forest { background: var(--forest, #4f6a38); }
.ds-tag-steel { background: var(--steel, #3f547c); }
.ds-tag-violet { background: var(--violet, #6a3d7a); }
.ds-tag-brick { background: var(--brick, #b83a28); }
.ds-ghost { color: color-mix(in srgb, var(--ink, #0e0d0c) 46%, var(--board, #c45a14)); font-family: "Chivo Mono", ui-monospace, monospace; font-size: 11px; }

.ds-phase { display: flex; gap: 10px; align-items: center; font-family: "Chivo Mono", ui-monospace, monospace; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--ink, #0e0d0c); margin: 0; }
.ds-stamp { background: var(--ink, #0e0d0c); color: var(--tissue, #f3efe6); padding: 4px 9px 2px; text-transform: uppercase; letter-spacing: -0.02em; font-weight: 800; font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 15px; }
.ds-stamp.ds-blink { animation: ds-chip-pulse 1s steps(2) infinite; }
@keyframes ds-chip-pulse { 50% { opacity: 0.28; } }

.ds-table { border: 2px solid var(--ink, #0e0d0c); background: var(--board, #c45a14); }
.ds-flute { height: 16px; background: repeating-linear-gradient(90deg, var(--kraft, #8f3d0c) 0 4px, var(--flute, #a34810) 4px 5px, var(--board, #c45a14) 5px 10px); border-bottom: 2px solid var(--ink, #0e0d0c); }
.ds-end { display: grid; grid-template-columns: 72px 1fr auto; gap: 12px; align-items: center; width: 100%; padding: 10px 8px; border: 0; border-bottom: 1px solid color-mix(in srgb, var(--ink, #0e0d0c) 22%, var(--board, #c45a14)); background: color-mix(in srgb, var(--tissue, #f3efe6) 55%, var(--board, #c45a14)); color: var(--ink, #0e0d0c); text-align: left; cursor: pointer; transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1); }
.ds-end:hover { background: var(--tissue, #f3efe6); }
.ds-end:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }
.ds-end:active { transform: translateX(48px); background: var(--tissue, #f3efe6); box-shadow: 14px 10px 24px color-mix(in srgb, var(--ink, #0e0d0c) 32%, transparent); }
.ds-thumb { width: 52px; height: 52px; display: block; background: linear-gradient(135deg, transparent 46%, var(--ink, #0e0d0c) 46% 54%, transparent 54%), var(--tissue, #f3efe6); border: 1px solid var(--ink, #0e0d0c); }
.ds-end-copy { display: flex; flex-direction: column; gap: 2px; }
.ds-end-copy .ds-code { font-family: "Chivo Mono", ui-monospace, monospace; font-size: 11px; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; font-variant-numeric: tabular-nums; }
.ds-end-copy strong { font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; }
.ds-tag { display: inline-block; padding: 1px 6px 0; font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 13px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--tissue, #f3efe6); background: var(--ink, #0e0d0c); }
.ds-tag-forest { background: var(--forest, #4f6a38); }

.ds-drawer { width: min(428px, 100%); display: flex; flex-direction: column; box-shadow: 14px 10px 24px color-mix(in srgb, var(--ink, #0e0d0c) 32%, transparent); animation: ds-lid-open 220ms cubic-bezier(0.2, 0.8, 0.2, 1); transform-origin: right center; }
.ds-lid { height: 28px; flex: none; background: repeating-linear-gradient(90deg, var(--kraft, #8f3d0c) 0 4px, var(--flute, #a34810) 4px 5px, var(--board, #c45a14) 5px 10px); border: 2px solid var(--ink, #0e0d0c); border-bottom-width: 3px; }
.ds-tissue { flex: 1; padding: 20px; background: var(--tissue, #f3efe6); color: var(--ink, #0e0d0c); }
.ds-close { float: right; font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 16px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; border: 1px solid var(--ink, #0e0d0c); border-radius: 3px; background: var(--ink, #0e0d0c); color: var(--tissue, #f3efe6); padding: 9px 18px; cursor: pointer; }
.ds-close:hover { background: color-mix(in srgb, var(--ink, #0e0d0c) 88%, var(--board, #c45a14)); }
.ds-close:focus-visible { outline: 2px solid var(--ink, #0e0d0c); outline-offset: 3px; }
.ds-tissue .ds-code { font-family: "Chivo Mono", ui-monospace, monospace; font-size: 11px; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; margin: 0 0 4px; }
.ds-lid-title { margin: 4px 0 14px; font-family: "Big Shoulders Condensed", "Arial Narrow", sans-serif; font-size: 36px; font-weight: 800; letter-spacing: -0.03em; line-height: 0.9; text-transform: uppercase; }
.ds-lid-body { font-family: "Chivo Mono", ui-monospace, monospace; font-size: 13px; font-weight: 400; max-width: 62ch; }
@keyframes ds-lid-open { from { transform: perspective(900px) rotateY(-32deg) translateX(36px); opacity: 0; } to { transform: none; opacity: 1; } }

.ds-empty { position: relative; border: 2px solid var(--ink, #0e0d0c); background: var(--board, #c45a14); }
.ds-empty .ds-flute { height: 16px; background: repeating-linear-gradient(90deg, var(--kraft, #8f3d0c) 0 4px, var(--flute, #a34810) 4px 5px, var(--board, #c45a14) 5px 10px); border-bottom: 2px solid var(--ink, #0e0d0c); }
.ds-slot { display: grid; grid-template-columns: 72px 1fr 88px; gap: 10px; align-items: center; min-height: 64px; padding: 8px; border-bottom: 1px solid color-mix(in srgb, var(--ink, #0e0d0c) 22%, var(--board, #c45a14)); background: color-mix(in srgb, var(--tissue, #f3efe6) 55%, var(--board, #c45a14)); }
.ds-well { width: 52px; height: 52px; border: 1px solid var(--ink, #0e0d0c); background: var(--tissue, #f3efe6); }
.ds-rib { height: 10px; background: repeating-linear-gradient(90deg, var(--kraft, #8f3d0c) 0 4px, var(--flute, #a34810) 4px 5px, var(--board, #c45a14) 5px 10px); border: 1px solid color-mix(in srgb, var(--ink, #0e0d0c) 35%, var(--board, #c45a14)); }
.ds-runout { height: 8px; background: color-mix(in srgb, var(--ink, #0e0d0c) 12%, var(--tissue, #f3efe6)); }
.ds-empty-copy { position: absolute; inset: 14px 0 0; display: grid; place-items: center; margin: 0; padding: 24px; text-align: center; font-family: "Chivo Mono", ui-monospace, monospace; font-size: 13px; font-weight: 500; color: var(--ink, #0e0d0c); background: color-mix(in srgb, var(--board, #c45a14) 35%, transparent); }
